//Veja como configurar conforme o Banco de Dados
//https://www.adianti.com.br/framework-quickstart

/**
 * Conexão com o banco, lida do .env do CNPJ-full (docs/arquitetura.md).
 *
 * A pasta do CNPJ-full vem de app/config/application.php > 'cnpj_full' > 'path'
 * (caminho relativo à pasta www/cnpjrfb, ou absoluto). O .env fica na raiz dessa
 * pasta, o mesmo arquivo que o Python usa, então a configuração do banco fica
 * num lugar só. Nomes das variáveis: .env.example do CNPJ-full.
 *
 * Sem .env (ou sem CNPJ_DB_TIPO e CNPJ_DB_ARQUIVO nele), usa o SQLite padrão
 * do cnpjrfb: app/database/cnpjrfb.db.
 */

$pastaSistema = dirname(__DIR__, 2); // www/cnpjrfb

// Pasta do CNPJ-full informada no application.php
$config = class_exists('AdiantiApplicationConfig') ? AdiantiApplicationConfig::get() : [];
if (!isset($config['cnpj_full'])) {
    $config = include __DIR__.'/application.php';
}
$pastaCnpjFull = trim((string) ($config['cnpj_full']['path'] ?? ''));
if ($pastaCnpjFull === '') {
    $pastaCnpjFull = 'app/CNPJ-full';
}
if (preg_match('#^([A-Za-z]:)?[\\\\/]#', $pastaCnpjFull) !== 1) {
    $pastaCnpjFull = $pastaSistema.'/'.$pastaCnpjFull;
}
$pastaCnpjFull = rtrim($pastaCnpjFull, '\\/');

// O .env tem a senha do banco: o Apache não pode servir a pasta do CNPJ-full
if (is_dir($pastaCnpjFull) && !is_file($pastaCnpjFull.'/.htaccess')) {
    @file_put_contents($pastaCnpjFull.'/.htaccess', "Require all denied\n");
}

// Lê o .env linha a linha (CHAVE=valor, # é comentário). Não usar parse_ini_file():
// ele dá erro de sintaxe com os comentários do .env.example do CNPJ-full.
$env = [];
$arquivoEnv = $pastaCnpjFull.'/.env';
if (is_file($arquivoEnv)) {
    foreach (file($arquivoEnv, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) as $linha) {
        $linha = trim($linha);
        if ($linha === '' || $linha[0] === '#' || strpos($linha, '=') === false) {
            continue;
        }
        [$chave, $valor] = array_map('trim', explode('=', $linha, 2));
        $aspas = $valor[0] ?? '';
        if (strlen($valor) > 1 && ($aspas === '"' || $aspas === "'") && substr($valor, -1) === $aspas) {
            $valor = substr($valor, 1, -1);
        }
        $env[$chave] = $valor;
    }
}

// CNPJ_DB_TIPO (nomes do CNPJ-full) -> type do Adianti
$tipos = ['postgres' => 'pgsql', 'mysql' => 'mysql', 'sqlserver' => 'sqlsrv', 'oracle' => 'oracle', 'sqlite' => 'sqlite'];
$tipo  = $env['CNPJ_DB_TIPO'] ?? 'sqlite';

if ($tipo === 'sqlite') {
    // CNPJ_DB_ARQUIVO é relativo à pasta do CNPJ-full (igual ao Python)
    $nome = 'app/database/cnpjrfb.db';
    $arquivo = $env['CNPJ_DB_ARQUIVO'] ?? '';
    if ($arquivo !== '') {
        $absoluto = preg_match('#^([A-Za-z]:)?[\\\\/]#', $arquivo) === 1;
        $nome = $absoluto ? $arquivo : $pastaCnpjFull.'/'.$arquivo;
    }
    return [
         "host" => ""
        ,"port" => ""
        ,"name" => $nome
        ,"user" => ""
        ,"pass" => ""
        ,"type" => "sqlite"
        ,"prep" => "1"
        ,"slog" => "SystemSqlLogService"
    ];
}

return [
     "host" => $env['CNPJ_DB_HOST'] ?? ''
    ,"port" => $env['CNPJ_DB_PORTA'] ?? ''
    ,"name" => $env['CNPJ_DB_NOME'] ?? ''
    ,"user" => $env['CNPJ_DB_USUARIO'] ?? ''
    ,"pass" => $env['CNPJ_DB_SENHA'] ?? ''
    ,"type" => $tipos[$tipo] ?? $tipo
    ,"prep" => "1"
    ,"slog" => "SystemSqlLogService"
];
